cells={(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v}
# Generate tile placements for each possible 2x2 window; square + Ls (omit corner)
tiles=[]
for r in range(6):
 for c in range(6):
  box={(r+i,c+j) for i in range(2) for j in range(2)}
  if box<=cells:
   tiles.append(('S',box))
  for miss in ((0,0),(0,1),(1,0),(1,1)):
   t=box-{(r+miss[0],c+miss[1])}
   if t<=cells: tiles.append((f'L{miss}',t))
sol=[]
def rec(rem, chosen, squares):
 if not rem:
  if squares==1: sol.append(chosen[:])
  return
 if squares>1: return
 p=min(rem)
 for typ,t in tiles:
  if p in t and t<=rem and (typ!='S' or squares==0):
   rec(rem-t,chosen+[(typ,t)],squares+(typ=='S'))
rec(cells,[],0)
len(sol), sol[:3]
